solution.solution.cpp:
bool inRange(int value, int low, int high)
{
    return value >= low && value <= high;
}

unitTests:
TEST("inside the range") { CHECK(inRange(5, 1, 10)); }
TEST("the ends are included") { CHECK(inRange(1, 1, 10)); CHECK(inRange(10, 1, 10)); }
TEST("outside the range") { CHECK(!inRange(0, 1, 10)); CHECK(!inRange(11, 1, 10)); }
TEST("big values below a small range") { CHECK(!inRange(50, 1, 10)); CHECK(!inRange(-5, 1, 10)); }

